  var LESHEM = '\u05DC\u05B0\u05E9\u05B5\u05C1\u05DD \u05D9\u05B4\u05D7\u05D5\u05BC\u05D3 \u05E7\u05D5\u05BC\u05D3\u05B0\u05E9\u05B8\u05C1\u05D0 \u05D1\u05B0\u05BC\u05E8\u05B4\u05D9\u05DA\u05B0 \u05D4\u05D5\u05BC\u05D0 \u05D5\u05BC\u05E9\u05B0\u05C1\u05DB\u05B4\u05D9\u05E0\u05B0\u05EA\u05B5\u05BC\u05D9\u05D4\u05BC, \u05D1\u05B4\u05BC\u05D3\u05B0\u05D7\u05B4\u05D9\u05DC\u05D5\u05BC \u05D5\u05BC\u05E8\u05B0\u05D7\u05B4\u05D9\u05DE\u05D5\u05BC, \u05DC\u05B0\u05D9\u05B7\u05D7\u05B2\u05D3 \u05E9\u05B5\u05C1\u05DD \u05D9"\u05D4 \u05D1\u05D5"\u05D4 \u05D1\u05B0\u05BC\u05D9\u05B4\u05D7\u05D5\u05BC\u05D3\u05B8\u05D0 \u05E9\u05B0\u05C1\u05DC\u05B4\u05D9\u05DD \u05D1\u05B0\u05BC\u05E9\u05B5\u05C1\u05DD \u05DB\u05B8\u05BC\u05DC \u05D9\u05B4\u05E9\u05B0\u05C2\u05E8\u05B8\u05D0\u05B5\u05DC. ';
  var HINENI = "\u05D4\u05B4\u05E0\u05B0\u05E0\u05B4\u05D9 \u05DE\u05D5\u05BC\u05DB\u05B8\u05DF \u05D5\u05BC\u05DE\u05B0\u05D6\u05BB\u05DE\u05B8\u05BC\u05DF \u05DC\u05B0\u05E7\u05B7\u05D9\u05B5\u05BC\u05DD \u05DE\u05B4\u05E6\u05B0\u05D5\u05B7\u05EA \u05E2\u05B2\u05E9\u05B5\u05C2\u05D4 \u05E9\u05B6\u05C1\u05DC \u05E1\u05B0\u05E4\u05B4\u05D9\u05E8\u05B7\u05EA \u05D4\u05B8\u05E2\u05B9\u05DE\u05B6\u05E8, \u05DB\u05B0\u05BC\u05DE\u05D5\u05B9 \u05E9\u05B6\u05C1\u05DB\u05B8\u05BC\u05EA\u05D5\u05BC\u05D1 \u05D1\u05B7\u05BC\u05EA\u05BC\u05D5\u05B9\u05E8\u05B8\u05D4: " + VERSE + " \u05D5\u05B4\u05D9\u05D4\u05B4\u05D9 \u05E0\u05B9\u05E2\u05B7\u05DD \u05D9\u05B0\u05D9\u05B8 \u05D0\u05B1\u05DC\u05B9\u05D4\u05B5\u05D9\u05E0\u05D5\u05BC \u05E2\u05B8\u05DC\u05B5\u05D9\u05E0\u05D5\u05BC, \u05D5\u05BC\u05DE\u05B7\u05E2\u05B2\u05E9\u05B5\u05C2\u05D4 \u05D9\u05B8\u05D3\u05B5\u05D9\u05E0\u05D5\u05BC \u05DB\u05BC\u05D5\u05B9\u05E0\u05B0\u05E0\u05B8\u05D4 \u05E2\u05B8\u05DC\u05B5\u05D9\u05E0\u05D5\u05BC, \u05D5\u05BC\u05DE\u05B7\u05E2\u05B2\u05E9\u05B5\u05C2\u05D4 \u05D9\u05B8\u05D3\u05B5\u05D9\u05E0\u05D5\u05BC \u05DB\u05BC\u05D5\u05B9\u05E0\u05B0\u05E0\u05B5\u05D4\u05D5\u05BC.";
  var BRACHA = "\u05D1\u05B8\u05BC\u05E8\u05D5\u05BC\u05DA\u05B0 \u05D0\u05B7\u05EA\u05B8\u05BC\u05D4 \u05D9\u05B0\u05D9\u05B8 \u05D0\u05B1\u05DC\u05B9\u05D4\u05B5\u05D9\u05E0\u05D5\u05BC \u05DE\u05B6\u05DC\u05B6\u05DA\u05B0 \u05D4\u05B8\u05E2\u05D5\u05B9\u05DC\u05B8\u05DD, \u05D0\u05B2\u05E9\u05B6\u05C1\u05E8 \u05E7\u05B4\u05D3\u05B0\u05BC\u05E9\u05B8\u05C1\u05E0\u05D5\u05BC \u05D1\u05B0\u05BC\u05DE\u05B4\u05E6\u05B0\u05D5\u05B9\u05EA\u05B8\u05D9\u05D5 \u05D5\u05B0\u05E6\u05B4\u05D5\u05B8\u05BC\u05E0\u05D5\u05BC \u05E2\u05B7\u05DC \u05E1\u05B0\u05E4\u05B4\u05D9\u05E8\u05B7\u05EA \u05D4\u05B8\u05E2\u05B9\u05DE\u05B6\u05E8.";
  var HARACHAMAN = "\u05D4\u05B8\u05E8\u05B7\u05D7\u05B2\u05DE\u05B8\u05DF \u05D4\u05D5\u05BC\u05D0 \u05D9\u05B7\u05D7\u05B2\u05D6\u05B4\u05D9\u05E8 \u05DC\u05B8\u05E0\u05D5\u05BC \u05E2\u05B2\u05D1\u05D5\u05B9\u05D3\u05B7\u05EA \u05D1\u05B5\u05BC\u05D9\u05EA \u05D4\u05B7\u05DE\u05B4\u05BC\u05E7\u05B0\u05D3\u05B8\u05BC\u05E9\u05C1 \u05DC\u05B4\u05DE\u05B0\u05E7\u05D5\u05B9\u05DE\u05B8\u05D4\u05BC, \u05D1\u05B4\u05BC\u05DE\u05B0\u05D4\u05B5\u05E8\u05B8\u05D4 \u05D1\u05B0\u05D9\u05B8\u05DE\u05B5\u05D9\u05E0\u05D5\u05BC, \u05D0\u05B8\u05DE\u05B5\u05DF \u05E1\u05B6\u05DC\u05B8\u05D4.";
  var BARUCH_SHEM = "\u05D1\u05B8\u05BC\u05E8\u05D5\u05BC\u05DA\u05B0 \u05E9\u05B5\u05C1\u05DD \u05DB\u05B0\u05BC\u05D1\u05D5\u05B9\u05D3 \u05DE\u05B7\u05DC\u05B0\u05DB\u05D5\u05BC\u05EA\u05D5\u05B9 \u05DC\u05B0\u05E2\u05D5\u05B9\u05DC\u05B8\u05DD \u05D5\u05B8\u05E2\u05B6\u05D3.";
  var RIBONO_A = "\u05E8\u05B4\u05D1\u05BC\u05D5\u05B9\u05E0\u05D5\u05B9 \u05E9\u05B6\u05C1\u05DC \u05E2\u05D5\u05B9\u05DC\u05B8\u05DD, \u05D0\u05B7\u05EA\u05B8\u05BC\u05D4 \u05E6\u05B4\u05D5\u05B4\u05BC\u05D9\u05EA\u05B8\u05E0\u05D5\u05BC \u05E2\u05B7\u05DC \u05D9\u05B0\u05D3\u05B5\u05D9 \u05DE\u05B9\u05E9\u05B6\u05C1\u05D4 \u05E2\u05B7\u05D1\u05B0\u05D3\u05B6\u05BC\u05DA\u05B8 \u05DC\u05B4\u05E1\u05B0\u05E4\u05B9\u05BC\u05E8 \u05E1\u05B0\u05E4\u05B4\u05D9\u05E8\u05B7\u05EA \u05D4\u05B8\u05E2\u05B9\u05DE\u05B6\u05E8, \u05DB\u05B0\u05BC\u05D3\u05B5\u05D9 \u05DC\u05B0\u05D8\u05B7\u05D4\u05B2\u05E8\u05B5\u05E0\u05D5\u05BC \u05DE\u05B4\u05E7\u05B0\u05BC\u05DC\u05B4\u05E4\u05BC\u05D5\u05B9\u05EA\u05B5\u05D9\u05E0\u05D5\u05BC \u05D5\u05BC\u05DE\u05B4\u05D8\u05BB\u05BC\u05DE\u05B0\u05D0\u05D5\u05B9\u05EA\u05B5\u05D9\u05E0\u05D5\u05BC, \u05DB\u05B0\u05BC\u05DE\u05D5\u05B9 \u05E9\u05B6\u05C1\u05DB\u05B8\u05BC\u05EA\u05B7\u05D1\u05B0\u05EA\u05B8\u05BC \u05D1\u05B0\u05BC\u05EA\u05D5\u05B9\u05E8\u05B8\u05EA\u05B6\u05DA\u05B8: " + VERSE + " \u05DB\u05B0\u05BC\u05D3\u05B5\u05D9 \u05E9\u05B6\u05C1\u05D9\u05B4\u05BC\u05D8\u05B8\u05BC\u05D4\u05B2\u05E8\u05D5\u05BC \u05E0\u05B7\u05E4\u05B0\u05E9\u05C1\u05D5\u05B9\u05EA \u05E2\u05B7\u05DE\u05B0\u05BC\u05DA\u05B8 \u05D9\u05B4\u05E9\u05B0\u05C2\u05E8\u05B8\u05D0\u05B5\u05DC \u05DE\u05B4\u05D6\u05BB\u05BC\u05D4\u05B2\u05DE\u05B8\u05EA\u05B8\u05DD. \u05D5\u05BC\u05D1\u05B0\u05DB\u05B5\u05DF \u05D9\u05B0\u05D4\u05B4\u05D9 \u05E8\u05B8\u05E6\u05D5\u05B9\u05DF \u05DE\u05B4\u05DC\u05B0\u05BC\u05E4\u05B8\u05E0\u05B6\u05D9\u05DA\u05B8 \u05D9\u05B0\u05D9\u05B8 \u05D0\u05B1\u05DC\u05B9\u05D4\u05B5\u05D9\u05E0\u05D5\u05BC \u05D5\u05B5\u05D0\u05DC\u05B9\u05D4\u05B5\u05D9 \u05D0\u05B2\u05D1\u05D5\u05B9\u05EA\u05B5\u05D9\u05E0\u05D5\u05BC, \u05E9\u05B6\u05C1\u05D1\u05B4\u05BC\u05D6\u05B0\u05DB\u05D5\u05BC\u05EA \u05E1\u05B0\u05E4\u05B4\u05D9\u05E8\u05B7\u05EA \u05D4\u05B8\u05E2\u05B9\u05DE\u05B6\u05E8 \u05E9\u05B6\u05C1\u05E1\u05B8\u05BC\u05E4\u05B7\u05E8\u05B0\u05EA\u05B4\u05BC\u05D9 \u05D4\u05B7\u05D9\u05BC\u05D5\u05B9\u05DD, \u05D9\u05B0\u05EA\u05BB\u05E7\u05B7\u05BC\u05DF \u05DE\u05B7\u05D4 \u05E9\u05B6\u05BC\u05C1\u05E4\u05B8\u05BC\u05D2\u05B7\u05DE\u05B0\u05EA\u05B4\u05BC\u05D9 \u05D1\u05B4\u05BC\u05E1\u05B0\u05E4\u05B4\u05D9\u05E8\u05B8\u05D4 ";
  var RIBONO_B = ", \u05D5\u05B0\u05D0\u05B6\u05D8\u05B8\u05BC\u05D4\u05B5\u05E8 \u05D5\u05B0\u05D0\u05B6\u05EA\u05B0\u05E7\u05B7\u05D3\u05B5\u05BC\u05E9\u05C1 \u05D1\u05B4\u05BC\u05E7\u05B0\u05D3\u05BB\u05E9\u05B8\u05BC\u05C1\u05D4 \u05E9\u05B6\u05C1\u05DC \u05DE\u05B7\u05E2\u05B0\u05DC\u05B8\u05D4, \u05D5\u05B0\u05E2\u05B7\u05DC \u05D9\u05B0\u05D3\u05B5\u05D9 \u05D6\u05B6\u05D4 \u05D9\u05BB\u05E9\u05B0\u05C1\u05E4\u05B7\u05BC\u05E2 \u05E9\u05B6\u05C1\u05E4\u05B7\u05E2 \u05E8\u05B7\u05D1 \u05D1\u05B0\u05BC\u05DB\u05B8\u05DC \u05D4\u05B8\u05E2\u05D5\u05B9\u05DC\u05B8\u05DE\u05D5\u05B9\u05EA, \u05D5\u05BC\u05DC\u05B0\u05EA\u05B7\u05E7\u05B5\u05BC\u05DF \u05D0\u05B6\u05EA \u05E0\u05B7\u05E4\u05B0\u05E9\u05C1\u05D5\u05B9\u05EA\u05B5\u05D9\u05E0\u05D5\u05BC \u05D5\u05B0\u05E8\u05D5\u05BC\u05D7\u05D5\u05B9\u05EA\u05B5\u05D9\u05E0\u05D5\u05BC \u05D5\u05B0\u05E0\u05B4\u05E9\u05B0\u05C1\u05DE\u05D5\u05B9\u05EA\u05B5\u05D9\u05E0\u05D5\u05BC \u05DE\u05B4\u05DB\u05B8\u05BC\u05DC \u05E1\u05B4\u05D9\u05D2 \u05D5\u05BC\u05E4\u05B0\u05D2\u05B8\u05DD, \u05D5\u05BC\u05DC\u05B0\u05D8\u05B7\u05D4\u05B2\u05E8\u05B5\u05E0\u05D5\u05BC \u05D5\u05BC\u05DC\u05B0\u05E7\u05B7\u05D3\u05B0\u05BC\u05E9\u05B5\u05C1\u05E0\u05D5\u05BC \u05D1\u05B4\u05BC\u05E7\u05B0\u05D3\u05BB\u05E9\u05B8\u05BC\u05C1\u05EA\u05B0\u05DA\u05B8 \u05D4\u05B8\u05E2\u05B6\u05DC\u05B0\u05D9\u05D5\u05B9\u05E0\u05B8\u05D4, \u05D0\u05B8\u05DE\u05B5\u05DF \u05E1\u05B6\u05DC\u05B8\u05D4.";
